using HeartOfTheRain.App.Celebrations;using System;using System.IO;using System.Linq;using System.Reflection;using System.Text.Json;
using HeartOfTheRain.App.Home;using HeartOfTheRain.App.PreLevel;using HeartOfTheRain.App.LevelComplete;using HeartOfTheRain.App.Journey;using HeartOfTheRain.App.Settings;using HeartOfTheRain.App.EndLevel;using HeartOfTheRain.M46;using HeartOfTheRain.M47;using HeartOfTheRain.M48;using UnityEngine;
class CompletionFlowChecks {
 static int checks,actions;static BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;static JsonSerializerOptions json=new JsonSerializerOptions{IncludeFields=true,WriteIndented=true};
 static void Check(bool yes,string why){checks++;if(!yes)throw new Exception(why);}static GameplayScreen Board(HomeLevelFlow f)=>(GameplayScreen)typeof(HomeLevelFlow).GetField("gameplay",hidden).GetValue(f);
 static PreLevelModal Pre(HomeLevelFlow f)=>f.gameObject.GetComponent<PreLevelModal>();static LevelCompleteModal Result(HomeLevelFlow f)=>f.gameObject.GetComponent<LevelCompleteModal>();
 static void Main(string[] args){var R=args[0];var M=Path.Combine(R,"CoreReference");var levels=Enumerable.Range(1,50).Select(n=>new TextAsset{text=File.ReadAllText(Path.Combine(M,"Data/Levels/C01_L"+n.ToString("000")+".json"))}).ToArray();var replays=JsonSerializer.Deserialize<CampaignReplaySet>(File.ReadAllText("PROJECT_REPLAY_PATH"),json);
 foreach(bool animationAvailable in new[]{true,false})foreach(var run in replays.runs){
  VictoryCelebrationPlayer.Enabled=ChapterCelebrationPlayer.Enabled=animationAvailable;
  var home=new HomePage();home.State.currentLevel=run.level;home.State.completedLevelsInChapter=run.level-1;var journey=home.gameObject.AddComponent<JourneyPage>();var f=new HomeLevelFlow{home=home,assets=new PreLevelAssets{gameplay=new GameplayUIAssets{boards=new BoardAssets{levels=levels}}},settingsAssets=new GameplaySettingsAssets(),endLevelAssets=new EndLevelAssets()};typeof(HomeLevelFlow).GetMethod("Start",hidden).Invoke(f,null);
  f.Open(run.level);Check(Pre(f).Data.rewardCoins==50&&Pre(f).Data.rewardStars==1,"pre-level reward mismatch");Pre(f).Requested("play");var board=Board(f);board.seed=(uint)run.seed;board.Initialize();f.Tick();var hud=board.GetComponent<GameplayHUD>();Check(hud.ResultRequested!=null,"missing win adapter");Check(!hud.ResultRequested(true,run.level)&&home.State.coins==1250,"visual preview minted rewards");
  foreach(var move in run.actions){TurnResult result;string error;Check(CampaignReplayRules.Apply(board.Model,move,out result,out error),"legal replay failed "+error);actions++;}
  Check(board.Model.Status=="Won","real replay not won");board.Busy=true;Check(!hud.ResultRequested(true,run.level),"opened before settled");board.Busy=false;
  Check(hud.ResultRequested(true,run.level),"real win rejected");Check(Result(f)==null,"victory modal still constructed");
  var victory=home.GetComponent<VictoryCelebrationPlayer>();var chapter=home.GetComponent<ChapterCelebrationPlayer>();
  if(animationAvailable){Check(run.level==50?chapter!=null&&chapter.IsVisible:victory!=null&&victory.IsVisible,"celebration did not open");Check(board.Paused&&board.ReviewInputBlocked&&hud.ExternalResultVisible(),"victory input not blocked");Check(home.State.coins==1300&&home.State.stars==1&&home.State.lives==5,"win balances");Check(home.State.currentLevel==Math.Min(50,run.level+1)&&home.State.completedLevelsInChapter==run.level,"win progress");Check(hud.ResultRequested(true,run.level)&&home.State.coins==1300,"duplicate callback");Check(f.StartingStockSnapshot().SequenceEqual(new[]{5,5,3,2}),"win changed booster stock");
  if(run.level==50){chapter.Finish();chapter.Finish();}else{victory.Finish();victory.Finish();}}
  Check(!Board(f)&&board.destroyed,"animation did not advance automatically");Check(home.State.coins==1300&&home.State.stars==1&&home.State.lives==5,"settlement changed or duplicated");Check(Result(f)==null,"follow-on victory modal was created");
  if(run.level==50){Check(journey.visible&&journey.requests.SequenceEqual(new[]{"view:1","next"}),"finale did not open chapter ending");Check(!Pre(f).IsVisible,"finale started unavailable board");f.Open(50);Check(Pre(f).Data.rewardCoins==0&&Pre(f).Data.rewardStars==0,"replay advertises repeat rewards");}
  else Check(Pre(f).IsVisible&&Pre(f).Data.level==run.level+1&&!Pre(f).Data.retry,"continue not using pre-level");
  Check(!hud.ResultRequested(true,run.level)&&home.State.coins==1300,"stale callback accepted");
 }
 VictoryCelebrationPlayer.Enabled=ChapterCelebrationPlayer.Enabled=true;
 // Preserve stock reservation and confirmed-exit/retry behavior in the modified full controller.
 var h=new HomePage();var flow=new HomeLevelFlow{home=h,assets=new PreLevelAssets{gameplay=new GameplayUIAssets{boards=new BoardAssets{levels=levels}}},settingsAssets=new GameplaySettingsAssets(),endLevelAssets=new EndLevelAssets()};typeof(HomeLevelFlow).GetMethod("Start",hidden).Invoke(flow,null);flow.Open(18);Pre(flow).Requested("toggle:0");Pre(flow).Requested("play");var first=Board(flow);Pre(flow).Requested("play");Check(Board(flow)==first&&flow.running.Count==1,"duplicate launch");first.Initialize();flow.Tick();Check(flow.StartingStockSnapshot()[0]==4,"launch stock");var end=new EndLevelSession();end.Open(18,5);EndLevelDecision decision;end.Confirm(5,out decision);first.gameObject.GetComponent<GameplaySettingsController>().Exit(decision);Check(flow.RetryVisible&&h.State.lives==4&&h.State.coins==1250&&h.State.stars==0,"exit regression");Pre(flow).Requested("play");var second=Board(flow);second.Initialize(true);flow.Tick();Check(!Board(flow)&&flow.RetryVisible&&flow.StartingStockSnapshot()[0]==4,"failed retry rollback");
 var report=new{status="PASS_REAL_WIN_ROUTING_WITH_FAKE_UI_HOST",checks,legalReplayActions=actions,realWinLevels=replays.runs.Select(v=>v.level),productionCode="Full HomeLevelFlow, LevelCompleteSession, BoardModel, starting stock and exit session",faked="Unity lifecycle, input, rendering, audio, Journey view, pre-level and animation presentation",UnityAPICompilation="NOT_RUN",UnityPlayMode="NOT_RUN"};File.WriteAllText(Path.Combine(R,"Validation/Completion_Flow_Checks.json"),JsonSerializer.Serialize(report,json));Console.WriteLine(JsonSerializer.Serialize(report,json));
 }
}
